def stage(id,label,kind,start,end,sources,note,short=None,basis='conditional_event'):
 d=dict(id=id,label=label,kind=kind,start=start,end=end,duration_basis=basis,sources=sources,note=note)
 if short:d['short_label']=short
 return '      - '+json.dumps(d,ensure_ascii=False)+'\n'
def replace(id,lines):
 global text
 text,n=re.subn(r'^      - \{id: '+re.escape(id)+r',.*\n',lambda m:lines,text,flags=re.M)
 assert n==1,id
replace('jp-im',stage('jp-gp','General practice specialty training (総合診療)','specialty',96,132,['jp-gp'],'At least three years after initial clinical training; required rotations, competence and completion review apply. The general practice specialty is distinct from internal medicine.','General practice',basis='specialty_minimum')+stage('jp-gp-assess','General practice specialty assessment','exam',132,132,['jp-gp'],'Completed training and the Board certification examination are distinct requirements; examination or registration waits are not estimated.',basis='credential_event')+stage('jp-gp-ready','General practice specialty training complete','practice_endpoint',132,132,['jp-gp'],'Family/general-practice training endpoint at eleven post-school years on this selected minimum route; specialist certification also requires the Board examination.'))
